  const partData=[['Engine','Top speed +10','speed',10],['Turbo','Acceleration +15','accel',15],['ECU','Acceleration +8','accel',8],['Transmission','Speed +6 · Accel +4','transmission',6],['Tires','Grip +10','handling',10],['Brakes','Braking +12','braking',12],['Suspension','Handling +8','handling',8],['Nitro','Boost power +8%','nitro',8]];
