  const persist = () => localStorage.setItem('streetVelocity', JSON.stringify({car:state.car,event:state.event,district:state.district,credits:state.credits,gems:state.gems,xp:state.xp,wins:state.wins,races:state.races,level:state.level,bestTime:state.bestTime,highestSpeed:state.highestSpeed,bestDrift:state.bestDrift,policeEscapes:state.policeEscapes,nightRaces:state.nightRaces,dailyClaimedDate:state.dailyClaimedDate,dailyStreak:state.dailyStreak,carUpgrades:state.carUpgrades,partUpgrades:state.partUpgrades,carStats:cars.map(({speed,accel,handling,braking})=>({speed,accel,handling,braking})),paint:state.paint,custom:state.custom,quality:state.quality,weather:state.weather,settings:state.settings}));
  const q = (s,root=document) => root.querySelector(s);
  const qa = (s,root=document) => [...root.querySelectorAll(s)];
  const car = () => {const base=cars[state.car],levels=state.partUpgrades[state.car]||{};const out={...base};partData.forEach(([name,,stat,gain],id)=>{const level=levels[id]||((id===0&&state.carUpgrades[state.car])||1),steps=Math.max(0,level-1);if(stat==='speed')out.speed=Math.min(410,out.speed+gain*steps);if(stat==='accel')out.accel=Math.min(400,out.accel+gain*steps);if(stat==='handling')out.handling=Math.min(400,out.handling+gain*steps);if(stat==='braking')out.braking=Math.min(400,out.braking+gain*steps);if(stat==='transmission'){out.speed=Math.min(410,out.speed+gain*steps);out.accel=Math.min(400,out.accel+4*steps);}});return out;};
