  function renderUpgrades(){const levels=state.partUpgrades[state.car]||{};const parts=partData.map(([name,detail,stat,gain],id)=>{const level=levels[id]||((id===0&&state.carUpgrades[state.car])||1);const cost=10000*level;return {name,detail,stat,gain,id,level,cost};});const selected=parts[0];q('#upgrades').innerHTML=`${shellHead('WORKSHOP · PERFORMANCE','UPGRADE SCREEN','Install a part upgrade to improve this car in your next race.') }<div class="upgrade-layout"><div class="engine-art">⚙</div><div class="panel upgrade-panel"><div class="eyebrow">${car().name.toUpperCase()} · SELECTED PART</div><h2>PERFORMANCE PARTS</h2><p class="subhead">Each purchase permanently improves this car.</p>${parts.slice(0,4).map(p=>`<div class="upgrade-item"><span>${p.name} · Lv ${p.level}</span><b>▲ ${p.detail}</b></div>`).join('')}<div class="event-meta"><span>AVAILABLE CREDITS</span><b style="color:var(--gold)">◉ ${state.credits.toLocaleString()}</b></div></div><div class="parts-grid">${parts.map(p=>`<button class="part-card" data-part-upgrade="${p.id}" aria-label="Upgrade ${p.name}"><span>⚙</span><b>${p.name} · Lv ${p.level}</b><small>${p.detail} · ◉ ${p.cost.toLocaleString()}</small></button>`).join('')}</div></div>`;}
