    q('#settings').innerHTML=`${shellHead('OPTIONS · PLAYER PREFERENCES','SETTINGS','Changes save automatically on this device.') }<div class="settings-layout"><div class="settings-nav"><button class="garage-tab active" data-settings-tab="graphics">GRAPHICS</button><button class="garage-tab" data-screen="controls">CONTROLS</button><button class="garage-tab" data-settings-tab="audio">AUDIO</button><button class="garage-tab" data-settings-tab="gameplay">GAMEPLAY</button></div><div class="panel setting-content"><div class="eyebrow">DISPLAY & PERFORMANCE</div><div class="setting-row"><div><b>Graphics quality</b><small>Adjust render detail and device load.</small></div><div class="segmented">${['Low','Medium','High'].map(x=>`<button class="${x===state.quality?'selected':''}" data-quality="${x}">${x}</button>`).join('')}</div></div><div class="setting-row"><div><b>Frame rate target</b><small>Canvas refresh cap.</small></div><div class="segmented">${['30','60','120'].map(x=>`<button class="${x===settings.fps?'selected':''}" data-setting-value="fps" data-value="${x}">${x}</button>`).join('')}</div></div>${toggle('Shadows','shadows','Enable road and vehicle shading.')}${toggle('Post processing','postProcessing','Enable glow and color effects.')}${toggle('Visual effects','vfx','Enable nitro and checkpoint glow.')}<div class="eyebrow" style="margin-top:20px">AUDIO MIXER</div>${[['Music','music'],['Sound effects','sfx']].map(([label,key])=>`<div class="range-row">${label}<input type="range" min="0" max="100" value="${settings[key]}" data-setting-range="${key}"><b>${settings[key]}%</b></div>`).join('')}<div class="eyebrow" style="margin-top:20px">GAMEPLAY</div>${toggle('Vibration','vibration','Use haptic feedback where the browser supports it.')}</div></div>`;
